# -*- coding: utf-8 -*-
"""生成 1/t 的 Q16 倒数表头文件（供 HLS 当 ROM 用）。

t 在硬件里是 Q8 整数 0..256；0 号项不会被读到，填 65535 兜底。
"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.abspath(os.path.join(HERE, "..", "01_hls", "src", "invt_lut.h"))
OUT2 = os.path.abspath(os.path.join(HERE, "..", "01_hls", "src", "recip_lut.h"))

vals = [65535] + [(65536 + i // 2) // i for i in range(1, 257)]

lines = [
    "// Auto-generated by 00_tools/gen_lut.py -- do not edit",
    "#pragma once",
    '#include "ap_int.h"',
    "static const ap_uint<17> INV_T_Q16[257] = {",
]
for k in range(0, 257, 8):
    row = ", ".join(str(v) for v in vals[k:k + 8])
    lines.append("    " + row + ("," if k + 8 < 257 else ""))
lines.append("};")

with open(OUT, "w", encoding="utf-8") as f:
    f.write("\n".join(lines) + "\n")

# ---------------------------------------------------------------------------
# Normalised reciprocal table for the guided filter.
#
# x is shifted left until it lands in [2^23, 2^24); then
#   mantissa = x / 2^23 = (256 + j) / 256,  j = (x >> 15) & 0xFF in [0,255]
#   RECIP[j] = round(2^32 / (256 + j))  ~=  2^24 / mantissa
# and 1/x = (RECIP[j] >> (23 - k)) / 2^24  with k = number of left shifts.
# Worst-case relative error ~0.4 % (8-bit mantissa, no interpolation).
# ---------------------------------------------------------------------------
rvals = [(2**32 + (256 + j) // 2) // (256 + j) for j in range(256)]

rlines = [
    "// Auto-generated by 00_tools/gen_lut.py -- do not edit",
    "#pragma once",
    '#include "ap_int.h"',
    "static const ap_uint<32> RECIP_LUT[256] = {",
]
for k in range(0, 256, 6):
    row = ", ".join(str(v) for v in rvals[k:k + 6])
    rlines.append("    " + row + ("," if k + 6 < 256 else ""))
rlines.append("};")

with open(OUT2, "w", encoding="utf-8") as f:
    f.write("\n".join(rlines) + "\n")

print(f"wrote {OUT}: {len(vals)} entries, min={min(vals)} max={max(vals)}")
print(f"wrote {OUT2}: {len(rvals)} entries, min={min(rvals)} max={max(rvals)}")

